#!/bin/bash
# New Agent DM in the visible chat card with engine $2 (Claude|Codex), then grant browser card $1 "Chat 조작 허용" (the person's path).
cd "$(dirname "$0")" || exit 1; N=${NODE:-node}; OUT="${EGDESK_QA_OUT:-/tmp/egdesk-real-window-qa}"; mkdir -p "$OUT"; CARD=${1:-egd-browser-card-1}; ENGINE=${2:-Claude}
$N mn.mjs exec 'const card=document.querySelector(".egd-chat-card"); [...card.querySelectorAll("button")].find(b=>(b.getAttribute("aria-label")||"")==="대화 목록으로")?.click(); return 1' >/dev/null; sleep 1
$N mn.mjs exec 'const card=document.querySelector(".egd-chat-card"); [...card.querySelectorAll("button")].find(b=>(b.getAttribute("aria-label")||b.textContent.trim())==="새 Agent DM")?.click(); return 1' >/dev/null; sleep 1.2
$N mn.mjs exec "const card=document.querySelector('.egd-chat-card'); const cur=[...card.querySelectorAll('button')].map(b=>b.getAttribute('aria-label')||'').find(l=>l.startsWith('AI 엔진'))||''; if (cur.startsWith('AI 엔진 $ENGINE')) return 'already'; [...card.querySelectorAll('button')].find(b=>(b.getAttribute('aria-label')||'').startsWith('AI 엔진'))?.click(); return 'opened'" >/dev/null; sleep 0.8
$N mn.mjs exec "const p=document.querySelector('.egd-codex-engine-panel'); if(!p) return 'no panel'; const b=[...p.querySelectorAll('button,[role=menuitemradio],[role=option]')].find(i=>(i.getAttribute('aria-label')||i.textContent.trim()).startsWith('$ENGINE')); b?.click(); document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true})); return !!b" >/dev/null; sleep 0.8
$N mn.mjs exec "const c=document.getElementById('$CARD'); [...c.querySelectorAll('button')].find(b=>(b.getAttribute('aria-label')||'')==='더보기')?.click(); return 1" >/dev/null; sleep 0.8
$N mn.mjs exec 'const items=[...document.querySelectorAll("[role=menuitem],[role=menuitemcheckbox],menuitem,button")].filter(i=>i.getBoundingClientRect().width>0); const it=items.find(i=>/^Chat 조작 허용$/.test((i.getAttribute("aria-label")||i.getAttribute("label")||i.textContent||"").trim())); it?.click(); return !!it' >/dev/null; sleep 1
$N mn.mjs exec 'const card=document.querySelector(".egd-chat-card"); const eng=[...card.querySelectorAll("button")].map(b=>b.getAttribute("aria-label")||"").find(l=>l.startsWith("AI 엔진"))||""; return eng.slice(0,26)+" | "+(card.innerText||"").replace(/\s+/g," ").slice(-70)' 300
